import{_ as r,C as a,o as n,c as i,j as e,a as o,E as h,a6 as c}from"./chunks/framework.CCKCzdWs.js";const d="/videos/picker-record-loop.mp4",l="/screenshots/picker-record.png",k=JSON.parse(`{"title":"Record a test","description":"Record clicks and fills across a site's pages with Piwi Picker into a runnable Playwright test, with checks of what the page shows and the evidence of each step, replayed before you copy it.","frontmatter":{"title":"Record a test","description":"Record clicks and fills across a site's pages with Piwi Picker into a runnable Playwright test, with checks of what the page shows and the evidence of each step, replayed before you copy it.","lang":"en-US","head":[["link",{"rel":"canonical","href":"https://piwitests.dev/features/record-actions.html"}],["meta",{"property":"og:url","content":"https://piwitests.dev/features/record-actions.html"}],["meta",{"property":"og:title","content":"Record a test | Piwi for Playwright"}],["meta",{"property":"og:description","content":"Record clicks and fills across a site's pages with Piwi Picker into a runnable Playwright test, with checks of what the page shows and the evidence of each step, replayed before you copy it."}]]},"headers":[],"relativePath":"features/record-actions.md","filePath":"features/record-actions.md","lastUpdated":1795281128000}`),p={name:"features/record-actions.md"};function g(u,t,f,m,w,b){const s=a("Needs");return n(),i("div",null,[t[0]||(t[0]=e("h1",{id:"record-a-test",tabindex:"-1"},[o("Record a test "),e("a",{class:"header-anchor",href:"#record-a-test","aria-label":'Permalink to "Record a test"'},"​")],-1)),h(s,{extension:""}),t[1]||(t[1]=e("p",null,[e("strong",null,"Record"),o(", the first tile of Piwi Picker's popup ("),e("code",null,"1"),o("), captures what you do on a site, across its pages, and turns it into a runnable Playwright test. The same recording becomes a "),e("a",{href:"./report-a-bug.html"},"bug report"),o(" once you mark something the page gets wrong; this page covers the recording itself and a test that passes.")],-1)),t[2]||(t[2]=e("figure",null,[e("video",{src:d,autoplay:"",loop:"",muted:"",playsinline:"",controls:"","aria-label":"Recording on a shop page: a search typed, a mug added to the cart, a coupon applied, each counted on the recording bar as a step, then Finish opens the finish panel with the steps and the test to copy"}),e("figcaption",null,"Each action becomes a step on the bar; Finish opens the finish panel.")],-1)),t[3]||(t[3]=c('<h2 id="starting-a-recording" tabindex="-1">Starting a recording <a class="header-anchor" href="#starting-a-recording" aria-label="Permalink to &quot;Starting a recording&quot;">​</a></h2><p>The first time on a site, Record asks the browser for access to it, so the recorder can follow you from page to page. The popup closes once the browser&#39;s prompt shows, and the recording starts when you allow it. If you refuse, nothing is recorded, and the next time you open the popup on that tab and site it says the recording did not start because Piwi Picker was not allowed there. While the recording runs, a red border marks the tab and the popup&#39;s first tile reads <strong>Finish (3)</strong>, with the number of steps so far.</p><p>The recorder captures clicks, double clicks, fills, checks, choices, drags, the names of chosen files (never their content), the keys that submit, close or move through a list, a click on what a hover shows, and the browser&#39;s <strong>Back</strong>, <strong>Forward</strong> and reload as a step to the page they reach. Each element is recorded with up to five locators that find it alone, ranked, so a replay has others to try when one no longer holds. Passwords are never captured, nor a card number, its security code or a one-time code in a field whose <code>autocomplete</code> names it: the test reads them from <code>process.env</code>.</p><h2 id="the-recording-bar" tabindex="-1">The recording bar <a class="header-anchor" href="#the-recording-bar" aria-label="Permalink to &quot;The recording bar&quot;">​</a></h2><p>A bar in a corner of the page lists the last steps and holds the recording&#39;s tools:</p><ul><li><strong>Check an element</strong>: pick an element, then choose what to check: its text, its value, its name as screen readers announce it, or its state (visible or hidden, usable or grayed out). The dialog starts from what the page shows, on its <strong>The page shows</strong> line; keeping it records an <code>expect(…)</code> that passes.</li><li><strong>Check the address</strong>: an <code>expect(page).toHaveURL(…)</code> of the page you are on, starting from its path.</li><li><strong>Something is missing</strong>: an element that should be on the page and is not.</li><li><strong>Screenshot</strong>: the page as it is now, while the debugging protocol takes the screenshots (below).</li><li><strong>Pause</strong> stops capturing without ending the recording, on every page and tab of it, so signing in or closing a banner stays out of the test, until <strong>Resume</strong>.</li><li><strong>Finish</strong> ends the recording and opens the finish panel.</li></ul><p>Changing what a check expects, or naming something missing, marks the page as wrong and makes the recording a bug report: <a href="./report-a-bug.html">Record a bug report</a>. When the bar covers something you need to click, its four-arrow button (<strong>Move this bar to another corner</strong>) moves it to the next corner, where it stays on every page. Under its buttons, the bar lists the <a href="#matching-functions">test functions</a> the steps look like, with a connection, then the evidence collected so far.</p><h2 id="evidence" tabindex="-1">Evidence <a class="header-anchor" href="#evidence" aria-label="Permalink to &quot;Evidence&quot;">​</a></h2><p>Every recording keeps the evidence a bug report needs, whether or not you mark anything wrong: the console errors, the failed requests, screenshots, a screenshot of each step, and the window&#39;s size, which the test sets with <code>page.setViewportSize</code>. In Chrome and Edge it reads them through the browser&#39;s <a href="./extension.html#the-debugging-bar">debugging protocol</a>, so Chrome shows its bar saying Piwi Picker started debugging the browser for as long as the recording runs; the recording bar says why, and Chrome&#39;s bar goes when you finish. In Firefox, or once that bar is cancelled, a script in the page reads the console and the requests instead, and the popup&#39;s <strong>Take a screenshot</strong> (<code>S</code>), which takes Replay&#39;s place while a recording runs, takes the screenshots. What is kept, and how: <a href="./report-a-bug.html#evidence">Evidence</a>. Nothing leaves the browser unless you send it.</p><h2 id="the-finish-panel" tabindex="-1">The finish panel <a class="header-anchor" href="#the-finish-panel" aria-label="Permalink to &quot;The finish panel&quot;">​</a></h2><p><strong>Finish</strong>, on the bar or in the popup, opens the finish panel: a <strong>Title</strong>, filled with the first page&#39;s own title (or, left empty, the first step in words), which names the test; the steps, each step a test function covers marked with its name; a line summing up the evidence; and a checkbox to keep or leave out the screenshot of each step. Then two rows of actions:</p><ul><li><strong>Copy test</strong> copies a runnable Playwright test that opens the addresses as recorded and waits for each page it opens. With steps that match your test functions, it calls them, and <strong>Without your functions</strong> copies the same test with locators only.</li><li><a href="./editor-recording.html#send-from-piwi-picker"><strong>Send to editor</strong></a>, with an editor paired, inserts it at the editor&#39;s cursor.</li><li><a href="./replay-a-bug-report.html"><strong>Replay</strong></a> plays the steps again in the tab, to see that each still finds its element.</li><li><strong>Copy report</strong> copies the recording as Markdown, <strong>Download .piwibug</strong> saves its steps, its test and its evidence as one <a href="/reference/bug-report-file.html">file</a>. Once a step is <a href="./report-a-bug.html">marked wrong</a>, <strong>Send to Piwi…</strong>, with a connection, sends it to your instance as a bug report after a <a href="./bug-reports.html#sending-a-report">preview</a>.</li><li><strong>Discard</strong> drops the recording.</li></ul><p>Until you discard it, the popup&#39;s first tile reads <strong>Review (7)</strong> and opens the finish panel again. Once a step is marked wrong, the panel is a bug report&#39;s and <strong>Copy test</strong> becomes <strong>Copy failing test</strong>: <a href="./report-a-bug.html#the-report">The report</a>.</p><figure><img src="'+l+'" alt="The finish panel after a recording: its title, seven steps and Copy test"><figcaption>The finish panel: every step, the test one click away.</figcaption></figure><h2 id="matching-functions" tabindex="-1">Matching functions <a class="header-anchor" href="#matching-functions" aria-label="Permalink to &quot;Matching functions&quot;">​</a></h2><p>With a connection, the recorder loads the <a href="./test-functions.html">function catalog</a> of the project mapped to the page and ranks, while you record, the functions the steps look like, under <strong>Matching test functions</strong> on the bar. In the copied test, a complete match becomes a call to your function. No AI: it scores your registered functions&#39; DOM patterns.</p><h2 id="limits" tabindex="-1">Limits <a class="header-anchor" href="#limits" aria-label="Permalink to &quot;Limits&quot;">​</a></h2><ul><li>It follows one site, in the top-level document only: see the <a href="./extension.html#limits">extension&#39;s limits</a>.</li><li><a href="./editor-recording.html">Recording from the editor</a> uses the same bar with the checks only: it marks nothing wrong, keeps no evidence and writes the code in the editor instead of a finish panel.</li></ul><h2 id="related" tabindex="-1">Related <a class="header-anchor" href="#related" aria-label="Permalink to &quot;Related&quot;">​</a></h2><ul><li><a href="./report-a-bug.html">Record a bug report</a>: the same recording, with what the page should show and the evidence</li><li><a href="./replay-a-bug-report.html">Replay a recording</a>: play recorded steps again in a tab</li><li><a href="/reference/bug-report-file.html">Bug report file</a>: what <strong>Download .piwibug</strong> saves, <code>steps.json</code> included</li><li><a href="./editor-recording.html#send-from-piwi-picker">Send to editor</a>: the test inserted in VS Code or a JetBrains IDE</li><li><a href="./extension.html">Browser extension</a>: the other tools, the permissions and the limits</li></ul>',20))])}const v=r(p,[["render",g]]);export{k as __pageData,v as default};
